import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives';
import { createText as __ } from '@/text';
import { pow, mul, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Texture } = ctx.THREE;

  // Root container; placement will be applied by the adapter.
  const root = new Group();

  // Atlas region (fallback to full image if missing).
  const atlasRect = (config.atlasRegion && config.atlasRegion.sourceRect) || {
    x: 0,
    y: 0,
    w: 512,
    h: 320,
  };
  const width = atlasRect.w;
  const height = atlasRect.h;
  const aspect = width / height;

  // Plane geometry sized to the region's aspect ratio.
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  geometry.translate(0, 0, 0);

  // Basic node material; texture will be assigned asynchronously.
  const material = new MeshBasicNodeMaterial();

  // Load the texture (sprite image) via the provided loader.
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Create mesh and add to root.
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Simple billboard: orient plane toward the active camera each frame.
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // No cinematic primitives for this node, but keep the hook for future extensions.
  const primitiveHandles = [];

  // Cleanup routine: dispose geometry, material, texture and kill any GSAP timelines.
  root.userData.cleanup = () => {
    // Dispose material and its texture.
    if (material) {
      material.dispose();
    }
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Dispose geometry.
    if (geometry) {
      geometry.dispose();
    }
    // Dispose primitives if any were created.
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    });
    // Kill all GSAP timelines attached to this node.
    gsap.globalTimeline.getChildren(true, false, false).forEach((t) => {
      if (t && t.data && t.data.node === root) {
        t.kill();
      }
    });
  };

  // Placeholder for event handlers (none required for this sprite node).
  root.userData.handlers = {};

  return root;
}
